$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5b7417c1bd6f4e8a1181f2e7295a3e28'] = 'Cette option vous permet d\'affecter le groupe comme groupe de clients par défaut. Le groupe de clients par défaut sera configuré par rapport à la dernière adresse ajoutée par le client.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ab2004936572b7bcf164741f383f4c97'] = 'Changer le groupe par défaut avec l\'adresse';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_307181015f28b24b5cf56a56f268fefc'] = 'Cette option vous permet de modifier le groupe client par défaut associé au pays dans cette section lorsque le client sélectionne une adresse par défaut ou lors du processus d\'achat. Si l\'adresse sélectionnée n\'a pas de numéro de TVA valide, le système passera au groupe client Prestashop par défaut';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f008d6b21c614caada820eac4e9ae732'] = 'Supprimer un client d\'un autre groupe';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_48cade9acdfa67cc5014f8e885463462'] = 'Cette option supprime le client des groupes auxquels il était précédemment affecté et le laisse uniquement affecté au groupe configuré par pays dans cette section. Le groupe par défaut sera remplacé par le groupe actuellement attribué.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ccca8b7e16706b70eb3862d8cac1cf3'] = 'Paramètres d\'activation';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c421a5582c9affbd59ce0fbe57a4060'] = 'Les pays de l\'UE sont sélectionnés par défaut. L\'option [Countries for validation] n\'est utile que pour ajouter ou supprimer des pays appartenant à l\'Union Européenne ou ayant un accord avec des opérations intra-communautaires. Dans une situation normale, cette option est prédéfinie et ne doit pas être modifiée. Tenez compte du fait que le nord de l\'Irlande est inclus pour les opérations intracommunautaires et appartient au Royaume-Uni (Angleterre).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1a7c23373b408af50cb839fbe7d52c85'] = 'Validation back-office';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_882cb664782409edd93fd5d3ab85efec'] = 'Activez la validation des numéros de TVA dans la section Adresse du Back-office.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_50da52ae50ce1c69d9ec84f9ae7de0e1'] = 'Certains modules utilisent des contrôleurs appartenant au back-office pour la création d\'adresses clients via des tâches cron ou via des processus. Pour que le module puisse valider les numéros de TVA de ces adresses créées, cette option doit être activée.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bb7bd05d489b31a0c31edfd4897745f4'] = 'Validation front-office';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9176ffc4cac7d0b19daba445c764c2b1'] = 'Activez la validation des numéros de TVA dans la section Adresse du Front-office lorsqu\'un client crée ou modifie une adresse ou lors du processus de paiement.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_32b4427fd2b69a2c80d21c213e50f974'] = 'Pays de validation';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f173aae292b6e3a5365cb4ac449d60b5'] = 'Sélectionnez les pays pour activer la validation. Vous ne devez pas modifier cette liste sauf si la réglementation des opérations intracommunautaires évolue et si les pays concernés sont modifiés.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2d59f051b72e3fab1863a7720267abf8'] = 'CTRL et cliquez ou cliquez et faites glisser pour sélectionner plusieurs options.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c9cc8cce247e49bae79f15173ce97354'] = 'Sauver';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b51d6159f43c28990c668ee0f5722e68'] = 'Tenez compte du fait que pour que l\'opération de détaxe soit juridiquement correcte, le commerçant, en plus du client, doit être enregistré avec une TVA intracommunautaire valide. Le système validera le numéro de TVA intracommunautaire du commerçant par VIES ou GOV.UK avant de l\'enregistrer dans la base de données.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4c4974ffdbc418a104b9ac8fe50329f2'] = 'TVA marchand';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c5e748d9e2d43bffbcf34fba6bf83c8'] = 'Insérez le numéro de TVA marchand (avec code ISO) auquel l\'entreprise est immatriculée pour les opérations intracommunautaires. Ecrire le numéro complet avec le code iso (Ex : FR17852960). Les numéros de TVA du Royaume-Uni ne sont pas autorisés.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1709b640f134a404881e88edc01258bc'] = 'Ceci est nécessaire pour l\'option de système de validation bidirectionnelle. Pourrait laisser vide si vous n\'utilisez pas le système de validation à 2 voies.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d927b3b03a13bf31b7eb8f6ff92e07ca'] = 'Afficher le message d\'avertissement dans l\'adresse';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8c0a80538a54ae2b99f5d930b34f65e2'] = 'Affiche des messages d\'avertissement dans la section adresse du compte du client lorsqu\'il n\'a pas de numéro de TVA valide enregistré, ou doit enregistrer un numéro de TVA (option de champ obligatoire activée) ou doit valider le champ de l\'entreprise (option de validation de l\'entreprise activée).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6bf5595b28f11a3701d3dc6c9d6e449d'] = 'Fonctionne uniquement dans Prestashop 1.7 ou supérieur';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e119406d93b7385c70d4b607a81bcf32'] = 'Ne pas autoriser le paiement lorsque l\'adresse est incomplète';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a2f3bd6da6361f19d81c48c65446422f'] = 'Cette option ne permet pas au client de poursuivre le processus d\'achat si l\'adresse sélectionnée comporte le champ numéro de TVA ou nom de société qui doit être validé ou renseigné (Selon les options de validation et de configuration du champ TVA sélectionnées). Option utile pour les clients qui avaient déjà des adresses enregistrées dans la base de données';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d2afdcacd59b06e5541e4c32b24581b7'] = 'Bloc de prix personnalisé';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6607b1376017ff8c5845ae0e911f962b'] = 'Ajoutez un texte personnalisé dans le bloc de prix du produit (en dessous du prix) et il s\'affichera lorsqu\'un client a sélectionné une adresse avec un numéro de TVA valide et est exonéré de taxe.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1b94355921381017449e017baaa43e5e'] = 'Il est fortement recommandé d\'utiliser le système de validation à 2 voies pour garantir l\'intégrité juridique de l\'exonération fiscale dans les transactions intracommunautaires, en vérifiant à la fois le numéro de TVA du commerçant et du client. Pour une validation à 2 voies, il est nécessaire de définir le numéro de TVA marchand dans les paramètres généraux. Si l\'option TVA marchand est vide, le système utilisera la validation unidirectionnelle dans tous les cas.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8dd10878b69a18f881af0c0e36247cb0'] = 'Système de validation';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_24b0f41249450fb2b8d43025022f44a8'] = 'Sélectionnez le système de validation du numéro de TVA. La validation unidirectionnelle vérifie et valide uniquement le numéro de TVA du client, même lorsque le commerçant n\'a pas de numéro de TVA valide. La validation bidirectionnelle envoie les informations sur le numéro de TVA du commerçant et le numéro de TVA du client et vérifie si les deux sont déjà enregistrés pour effectuer des opérations intracommunautaires avec exonération fiscale.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c106d4c676d2f70ee14fe9ac8b53a99'] = 'Fonctionne uniquement avec l\'option de système de validation [Format + API system] sélectionnée.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_147dc6e7f6af2b9b3bb0cf77bab90e41'] = 'Validation unidirectionnelle';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4792ea7be8342c48e29cf2eeae895962'] = 'Validation bidirectionnelle';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_29dcf8f9e61af7c1f9e4bbd16cf4f2cf'] = 'Mode validation';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c5a4695fbfd74fcfac2a3d505c66d43b'] = 'Cette option définit le mode de validation de la TVA. Le mode strict valide les numéros de TVA au format correct saisis par le client (Ex : FR01609493). Le mode intelligent valide les numéros de TVA même si le format n\'est pas inséré correctement par le client (Ex : FR-01609493, FR 01609493, FR01.609.493) et enregistre sous un format valide (Ex : FR01609493)';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_006576df800107db40832e2e0fd44931'] = 'Mode strict';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_dfea54ef85aa32f8489ae0f672d91c5a'] = 'Mode intelligent';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_94b93271d0dfce2b59ba77cc690415a3'] = 'Type de validation';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_99dd2d580dc5196d7e919645a054c28a'] = 'Cette option définit le type de validation TVA. Le mode de validation du format valide uniquement le format des numéros de TVA (Ex : FR01609493). La validation Format + API valide le format du numéro de TVA et le vérifie dans le système API VIES ou GOV.UK (recommandé pour l\'exonération de TVA).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5718f767fd5edcc521f57c23f4527725'] = 'Validation des formats';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_3b19c288b70dc9b277b83cb937d1df74'] = 'Format + validation du système API';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_54df18253716c9795f66ed2d4255833b'] = 'Validation de l\'entreprise';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93370977d5f528ed94a8f7cf6e7156be'] = 'S\'il est activé, le champ du nom de l\'entreprise sera validé avec les informations obtenues du système VIES/GOV.UK concernant le numéro de TVA. Si le client ne saisit pas le nom de l\'entreprise exactement tel qu\'il apparaît dans la base de données du système VIES/GOV.UK, l\'adresse ne sera pas validée avec ce numéro de TVA. Les clients précédents enregistrés dans la base de données avec un nom de société non encore validé mais une TVA valide, ils seront tenus de mettre à jour les informations d\'adresse avant d\'effectuer un achat dans le magasin.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ac50ccc149ebb161e8d8d19c3a6a946f'] = 'Pour éviter les erreurs dans les formulaires d\'adresse, assurez-vous que le champ \"société\" est affiché dans le formulaire. Si cette option est activée, ce champ sera tel que requis dans le formulaire d\'adresse.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_71e56d83a626d8268caf28e8eac3d64a'] = 'Insérer automatiquement le nom de l\'entreprise';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_52800a2170bf04b8329ec097aa422d63'] = 'Si cette option est activée, lorsque le client enregistre une adresse avec un numéro de TVA valide, le système insère le nom de la société enregistrée tiré du système VIES ou GOV.UK. Si le client a entré un autre nom de société dans le champ de la société, il sera remplacé par le nom correct enregistré dans le système.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_be496e62d1ca3007170567553e8441c0'] = 'Cette option n\'est pas compatible avec l\'option [Company validation] activée.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_de333ce299100de1723bb0d246f8845e'] = 'Autoriser la TVA en double';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c5c48e6b16c9c8e7d5f2924dba18076'] = 'Cette option active ou désactive pour autoriser différents enregistrements de clients avec les mêmes numéros de TVA.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_73e32e03f4ab7374222b68de7f97a2b6'] = 'Échec du système Ignorer l\'API';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9f5f6676c393f344b028ba9c4e77159f'] = 'Cette option ignore la validation en cas d\'échec du système API VIES/GOV.UK pendant le processus de validation. Le client peut continuer avec l\'enregistrement de l\'adresse et le paiement. Le numéro de TVA apparaîtra comme [Validated] et le statut du système apparaîtra en rouge comme [API request processing error] dans la liste de gestion de la TVA.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c65e5a2319190e3346c5ac53ad702b2b'] = 'Cette option ne fonctionne que dans la validation du système API.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d337d426b6c49df575234f8e7a001736'] = 'Enregistrer en majuscule';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ca36376b1a467f9f5c8f2fca7614721'] = 'Activez cette option pour enregistrer le numéro de TVA avec des lettres en majuscules lorsque des actions d\'ajout ou de mise à jour sont effectuées par le client dans le formulaire d\'adresse. Ex : FR01609493 au lieu de fr01609493';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_85fffe8f5074d606fa202fa5ae90d8bb'] = 'Liste noire';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a9fc6209ac169e499232af8c573ce560'] = 'Définissez les numéros de TVA dans une liste noire pour ne pas autoriser l\'enregistrement des clients avec certains de ces numéros. Écrivez un par un séparé par une virgule.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_7b13005d0082f3a02ff758d17debf5ad'] = 'Le module insérera le statut qui a été configuré dans cette section, lorsque le client passe une commande. Dans le cas du statut de la commande avec le numéro de TVA valide, celui-ci sera inséré en premier et juste après le statut suivant sera inséré en fonction des options de paiement choisies dans le processus d\'achat. Dans le cas du statut de la commande avec le numéro de TVA en attente de validation en raison d\'un échec du processus API, il sera inséré comme dernier et actuel statut de la commande, afin que le client sache que sa commande est en attente de validation avec le numéro de TVA.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c2f6f7927f37822c3b597d3686a44e70'] = 'Statut de la commande lorsque la TVA est validée';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5253f1fadf04ee3358f139e6040e1c80'] = 'Cette option configure le statut de la commande lorsque le numéro de TVA est validé avec succès. Ce statut sera affiché au début, juste avant le statut par défaut lors de la commande. Réglez [Disable] pour désactiver l\'option';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8a3ad48e7c2d0aa8fb38c2c03d13224a'] = 'Le module a créé son propre état appelé \"Numéro de TVA validé\". Mais vous pouvez utiliser n\'importe quel état personnalisé.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f735ac75c9a297e148d80eff382ebe4b'] = 'Statut de la commande lorsque le système API échoue';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d63a96b35bf6c72b9c138d0881421604'] = 'Cette option configure le statut de la commande lorsque le système API n\'a pas réussi à valider le numéro de TVA du client lorsque l\'option [Skip validation] a été activée et que le client a pu poursuivre la commande. Réglez [Disable] pour désactiver l\'option';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_833f65cc3fe8b58eb450caf32d51f3a9'] = 'Le module a créé son propre état appelé \"Numéro de TVA en attente de validation\". Mais vous pouvez utiliser n\'importe quel état personnalisé.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a81e07c3a2421768b9ee85c7c5e9df76'] = 'Affectation des groupes de clients par pays';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d850ba42b3ce90ace18bc59069f47c27'] = 'Le système procédera à la validation de toutes les adresses créées par le client tant qu\'il remplit les conditions de validation, que le type d\'adresse ait été choisi ou non dans l\'option indiquée dans cette section. Cette option sert uniquement à déterminer si le client sera exonéré de taxe lors du choix de l\'adresse lors du processus de paiement.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_66c36b9d18dd144a80435ebffd4b7ac1'] = 'Exonération de TVA';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8cb88c12dc7c0a45a4e0bea3050bd233'] = 'Cette option vous permet de supprimer les taxes des clients avec un numéro de TVA valide. Fonctionne pour tout type de validation (format ou système API).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bd5bece1f53fae4660f7673d3f1f00bd'] = 'Les prix des produits et les montants du panier seront affichés hors taxes.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0f35945c0ec8ece14d52e5fb9fdb6572'] = 'Type d\'adresse';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b85bee80d4cfb438d11cd19f63f7099f'] = 'Cette option vous permet de supprimer les taxes des clients avec un numéro de TVA valide dans le type d\'adresse déterminé (adresse de livraison, adresse de facturation ou les deux).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_042d32665de5a16cbbe0aeb373948f60'] = 'Si l\'option \"adresse de facturation et adresse de livraison\" est choisie, elle sera exonérée de taxes si l\'une des deux adresses ou les deux possèdent un numéro de TVA valide.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_601d8c4b9f72fc1862013c19b677a499'] = 'Adresse de facturation';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_af0f5bdc5be121b9307687aeeae38c17'] = 'Adresse de livraison';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ab330c76d81d3f96fb7d97d179c82bc7'] = 'Adresse de facturation et de livraison';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_09966285b248320d88be53355b466f21'] = 'Pays local';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_89a0979cda66d6e96fd0c7a12b9f8709'] = 'Cette option permet d\'attribuer votre pays local où les prix des produits et les commandes seront toujours taxés pour ce pays.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_41699887750c4faa22a2103e0db81c20'] = 'Exonération des groupes de clients';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b7d4d2cadf4db0aaab3bee7348154fd3'] = 'Cette option vous permet de supprimer les taxes pour certains groupes de clients, même si le numéro de TVA est valide ou non. Laissez vide pour le désactiver pour tous les groupes de clients. Si vous cochez un groupe, l\'exonération fiscale ne sera appliquée qu\'aux clients des groupes sélectionnés. Cette option est totalement indépendante de l\'option [VAT exemption] .';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0a365a829e2aecdb84fc372153aac60d'] = 'Texte légal de la facture';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8b006b1a87879287f5c7c0a382857d01'] = 'Ajoutez le texte légal sur la facture d\'une commande exonérée de TVA. Le texte sera ajouté ci-dessous au texte légal par défaut.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93f39badf1dd476bc3465e2366f91210'] = 'Note de facture';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_981bee80cb84e3422fe8e0de8d0694df'] = 'Ajouter une note sur la facture d\'une commande avec exonération de TVA. Le texte sera ajouté au-dessus des notes ajoutées.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fe7fe004668ea7015c4ccc584dbafcca'] = 'Ces options seront appliquées uniquement pour les pays sélectionnés pour validation dans l\'onglet [Activation] .';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f028f32e19d6c84ce3238a20459f6d42'] = 'NOTE : Ces options ne sont pas appliquées dans la validation des numéros de TVA depuis le Back-office.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_45c78c1b74b189ac8a5adc5b8e7a46c5'] = 'Seuls les modules de caisse que nous avons intégrés à 100% sont compatibles avec les options de cette section. Certaines de ces options peuvent ne pas fonctionner avec d\'autres modules de paiement, même ceux qui sont pris en charge par ce module et que nous mentionnons dans la liste de compatibilité. En effet, généralement, les modules qui gèrent la page de paiement utilisent leurs propres options et contrôleurs pour gérer les champs affichés dans le processus de paiement de leur module.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_221094f1579a69ea1aed37744bc540f2'] = 'Champ TVA';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fc268a0f6d8150b1c6881adb0014e3c6'] = 'Sélectionnez pour convertir le champ en facultatif ou obligatoire.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d6dc27fada47cb77f2dca329eacdbedc'] = 'Cette option ne fonctionne que pour les pays sélectionnés pour la validation.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e88e5e7b543453f0685b3b3593db4f9d'] = 'Champ facultatif';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_19f823c6453c2b1ffd09cb715214813d'] = 'champs requis';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6b8c4fd358a49601a93e161d47a1b054'] = 'Afficher uniquement pour l\'entreprise';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5a777cce9211514bfadce87220ed49ab'] = 'Activez cette option pour afficher le champ du numéro de TVA uniquement lorsque les clients insèrent un nom de société. Masquez le champ du numéro de TVA lorsqu\'il n\'y a pas de nom de société et bien que vous sélectionniez ce champ comme obligatoire, il deviendra facultatif.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c0e292ad508997ec1c2a15d772cb128f'] = 'Cette option ne fonctionne qu\'en front office. Le champ société sera affiché sous forme d\'adresse mais en backoffice dans tous les cas.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b021df6aac4654c454f46c77646e745f'] = 'Étiquette';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fbf1481544354c8de9e4f2fd5daff40d'] = 'Personnalisez le libellé du champ Numéro de TVA. Laissez vide pour l\'étiquette par défaut.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9b27e12d584b3438e811533b32e026e8'] = 'Légende';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ad07132b12ffdc38b5d7ef9859d98e0b'] = 'Personnalisez la légende du champ du numéro de TVA. Il est situé en dessous de l\'entrée. Laissez vide pour l\'étiquette par défaut.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f32f5ac2269b031043e213c23b4028eb'] = 'Le montant de %s est le seuil d\'exonération de TVA dans les numéros de TVA britanniques. Le taux de change doit être mis à jour quotidiennement par tâche CRON ou dans la section des devises.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_891cc5630f27487cbe9b32bce8a7a45a'] = 'Brexit';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9e2c3b66dc9c2c79111a8d11d9e9c332'] = 'Règles fiscales actives du Brexit pour les exportations vers le pays du Royaume-Uni.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_469dc620989561ab9ca079454545bb1e'] = 'Exonération de TVA dans les entreprises';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_53593000054652057f05c7ef687ba3e6'] = 'Cette option permet d\'être exonéré de TVA pour les entreprises avec un numéro de TVA britannique valide lorsque le montant total des produits du panier est égal ou inférieur à 135 GBP';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9b35e882da84307a7d230265e0577da0'] = 'Ne pas autoriser les commandes';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ddeb8f4307f430983d53cb41b34474e1'] = 'Cette option vous permet de choisir entre ne pas autoriser les achats d\'un montant inférieur à 135 GBP ou supérieur à 135 GBP.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8276092a35ba53068c987f7d7072809e'] = 'Plus de 135 GBP';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_539064c25c9433e56c0fae15fe794306'] = 'En dessous de 135 GBP';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_25b74a3fe7cc70e18e584e84d87875fa'] = 'Adresses mail';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2b50033cc81272b6fb76594eaf7bdb0f'] = 'Vous pouvez définir différentes adresses e-mail pour recevoir des e-mails de ce module. Vous devez écrire une adresse e-mail correcte. Pour plusieurs adresses, vous devez les écrire séparées par une virgule (Ex : test@test.com,test2@test2.com...).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e2d81b28527e0dea0a247c058f5b2897'] = 'E-mail d\'alerte API';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e1e436bcf0f1584ab270e8d6e0662f55'] = 'Envoyer une alerte par e-mail lorsque le client est enregistré et que la validation de la TVA par le système API échoue.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_242263e7b06b99d29a69bc72407b9696'] = 'Envoyer un e-mail au client lorsque l\'API échoue';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ca58cd422878a1b1ae81aee7fb02fce'] = 'Envoyer un e-mail au client l\'informant que le statut de la commande est en attente de validation du numéro de TVA, lors de la passation d\'une commande avec une adresse où le numéro de TVA n\'a pas pu être validé en raison d\'une défaillance du système API et l\'option [Skip validation] a été activé dans la section des paramètres de validation permettant au client de poursuivre l\'enregistrement de l\'adresse et la commande.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_16a607f72b9d08637169d3047b33e7b8'] = 'E-mail de validation client';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8e1d4cca72fb64311138e83a894aacd9'] = 'Envoyez un e-mail informant lorsque le client est enregistré et que la validation de la TVA par le système API est effectuée avec succès.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5be5f2a68a48c39d9c42b8a5fc2fbd17'] = 'Paramètres CRON pour vérifier les numéros de TVA';
