$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f8e69246c2f0444c12a03bdf5ffa39bf'] = 'Cette option ignore la validation en cas d\'échec du système API VIES/GOV.UK pendant le processus de validation. Le numéro de TVA apparaîtra comme [Validated] et le statut du système apparaîtra en rouge comme [API request processing error] dans la liste de gestion de la TVA.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_280ec81039b065382dd5173775fd82af'] = 'Supprimer le numéro de TVA vide';
