$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_754d8064fd8e110027273abe06c49ed4'] = 'Supprimer l\'adresse du client avec un numéro de TVA en double. Le système ne laissera que la première adresse créée et supprimera le reste avec un numéro de TVA en double si la TVA en double n\'est pas autorisée.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8b8c92abfa0d133ef1360066ef84c6e5'] = 'Envoyer un e-mail pour un numéro de TVA invalide';
