$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2e6fdff6558e75b8cbc9971155e7b97d'] = 'Cette action écrasera le nom de l\'entreprise que le client a déjà enregistré dans l\'adresse et le remplacera par le nom de l\'entreprise enregistré auprès de VIES ou GOV.UK.';
