$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_3ac8ea70f58e6f1ca2a0224e89e18d5e'] = 'Le pays %s n\'a pas le champ [company] dans le format d\'adresse. Pour éviter les erreurs dans la validation de ce champ, éditez le pays en ajoutant ce champ à votre format d\'adresse.';
