$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_725c965b569cde8598c1a64b3ef35b73'] = 'Le client qui a un numéro de TVA valide dans son adresse sera affecté au groupe sélectionné en fonction du pays de l\'adresse. Si le client a plusieurs adresses de pays différents, le système l\'ajoutera à autant de groupes qu\'il aura configuré par pays.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_34c58cceb7dfc65149c483c400538067'] = 'Option [Use as default group] :';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_024eabed4f59a4927c8723fe0c914b70'] = 'Si cette option est activée, lorsque le client est affecté à un groupe en fonction du pays de l\'adresse créée, ce groupe deviendra le groupe par défaut pour ce client. Si le client ajoute plus d\'adresses de différents pays, le groupe par défaut sera remplacé par le groupe auquel il a été ajouté en dernier.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_f600d68db7ba8913115bbd05608938ed'] = 'Option [Change default group with address] :';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_28d911ad25619fb5f1d88754dba47ebd'] = 'Si cette option est activée, lorsque le client sélectionne une certaine adresse pour passer sa commande dans le processus de paiement, le groupe par défaut du client sera remplacé par le groupe qui appartient au pays de l\'adresse sélectionnée.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_cc85ffddd57f9ec398514aef1ff9f298'] = 'Option [Remove customer from another groups] :';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_b6b4476becbf99ec2edffdb1d032898c'] = 'Si cette option est activée, le client sera affecté au groupe sélectionné par le pays de l\'adresse créée et sera supprimé du reste des groupes auxquels il appartenait auparavant et il sera affecté à ce groupe comme groupe par défaut. Cette option est utile lorsque vous souhaitez que le client n\'appartienne qu\'à un seul groupe et non à autant d\'adresses de différents pays qui ont été créées dans votre compte.';
$_MODULE['<{advancedvatmanager}prestashop>groupassignment_description_205bb8060e975b0776bc4dac2a655092'] = 'Lorsqu\'un client supprime une adresse de son compte, s\'il était affecté au groupe configuré pour ce pays et qu\'il n\'a plus d\'adresses avec le même pays, il sera supprimé de ce groupe. S\'il avait plus d\'adresses avec le même pays, il serait toujours attribué à ce groupe. Si le client est uniquement affecté à un groupe appartenant au pays de son adresse et qu\'il supprime l\'adresse, le système le supprimera de ce groupe et évitera d\'être laissé sans être affecté à aucun groupe et évitera ainsi un conflit dans les données de la base de données. , le système le réaffectera au groupe configuré par défaut dans Prestashop pour les clients enregistrés.';
$_MODULE['<{advancedvatmanager}prestashop>faq_4ab310316fb4c1fe03d7dfdd06bf899d'] = 'Lorsque le client a déjà enregistré une adresse avec un numéro de TVA valide, doit-il valider l\'adresse à chaque fois qu\'il passe une commande ?';
$_MODULE['<{advancedvatmanager}prestashop>faq_6bc9f601d4bd8ba5c5bdc320ef13ef1d'] = 'Lorsqu\'un client crée une adresse avec un numéro de TVA valide, le système la valide et enregistre le résultat de la validation dans la base de données, ainsi chaque fois qu\'il utilise la même adresse pour passer des commandes, il n\'aura pas à la valider à nouveau.';
$_MODULE['<{advancedvatmanager}prestashop>faq_d9c773e5a7c093f70c15421ce0649efe'] = 'Si la tâche périodique de validation du numéro de TVA est exécutée et que le numéro de TVA de ce client n\'est plus valide, le système le détectera et ce sera alors que le client ne sera plus exonéré de TVA jusqu\'à ce qu\'il insère à nouveau un numéro de TVA valide dans le direction.';
$_MODULE['<{advancedvatmanager}prestashop>faq_01b8106ef739e39e37ecd3b2aa59fbbf'] = 'Si le magasin a déjà des adresses clients avec des numéros de TVA enregistrés avant l\'installation du module, comment vérifier les adresses pour savoir si les clients ont saisi un numéro de TVA valide ou non ?';
$_MODULE['<{advancedvatmanager}prestashop>faq_212d8a06c6b54e3da48e6012dc0a23ff'] = 'Le module dispose d\'une fonction de tâche CRON pour vérifier les numéros de TVA de toutes les adresses clients qui sont déjà stockées dans la base de données. Une fois le module installé dans le magasin, le système vérifiera automatiquement les numéros de TVA des clients qui créent une adresse ou modifient celle qu\'ils ont déjà créée.';
$_MODULE['<{advancedvatmanager}prestashop>faq_1a0ea82254a62da89cadd91ba343b23c'] = 'Chaque fois que j\'exécute la tâche CRON pour vérifier les numéros de TVA des clients, le processus vérifie-t-il à nouveau toutes les adresses de la base de données ?';
$_MODULE['<{advancedvatmanager}prestashop>faq_7a2204718dfcecae6301eabebc53f85a'] = 'Le système vérifiera toutes les adresses des clients stockées dans la base de données à moins que l\'option \"Continuer le processus de numérisation à partir de la dernière adresse numérisée\" soit activée dans la section des paramètres CRON.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_8137db6ff17c5e78f769e8d116c634fe'] = 'Si l\'option Brexit est activée, le système calculera le montant total des produits du panier et s\'il est égal ou inférieur à %s (équivalent à 135 GBP) pour gérer les taxes dépend de chaque situation. Cette option permet la validation des numéros de TVA britanniques à l\'aide de l\'API du système GOV.UK tant que la validation de l\'API du système est sélectionnée.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_5af404f31fadca9508383fc002a20fd6'] = 'Ce système est mis à jour avec la nouvelle législation sur le Brexit. Le contrôle fiscal fonctionne comme suit :';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_0b83795dbb237b656e41ea8475c2d5f0'] = 'Montant du panier égal ou inférieur à 135 GBP (hors frais de port)';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_174aa92ed9957b09d0e9b6a273b1e54e'] = 'Entreprises ou particuliers sans numéro de TVA immatriculés au Royaume-Uni :';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_7e7ad63a16be4e910a637232f5d7adf5'] = 'Ce magasin facturera les taxes configurées dans le pays du Royaume-Uni.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_86dc36a261a4fa73344cf7ff30402bc1'] = 'Entreprises avec un numéro de TVA valide enregistré au Royaume-Uni :';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_016a392e7c93b7a65e77f8adbe3f3f37'] = 'Si vous avez activé l\'option \"exonération de TVA dans les entreprises\", alors le magasin ne facturera pas de taxes et la facture comportera le message \"autoliquidation : le client doit déclarer la TVA à HMRC\". Si l\'option est désactivée, elle facturera également des taxes.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_47073281137dc85bd341888a68616f0c'] = 'Montant du panier supérieur à 135 GBP (hors frais de port)';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_6a9414f4973ab35ac25ce88a92f007cf'] = 'Entreprises ou particuliers avec ou sans numéro de TVA immatriculés au Royaume-Uni :';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_fc817b43467d57cac1f70edc53e692e7'] = 'Ce magasin ne facturera pas les taxes.';
$_MODULE['<{advancedvatmanager}prestashop>brexit_description_08d59a447126862628e56d6bcd400c38'] = 'IMPORTANT : lors de l\'installation de ce module, le système a créé 232 États du Royaume-Uni (si ceux-ci n\'ont pas été créés précédemment) et a attribué l\'Irlande du Nord au Royaume-Uni conformément aux lois du Brexit. Cela améliore la création d\'adresses client en attribuant la province ou l\'état correct';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_1034384bb3e716cdcf48c7fd262b3b93'] = 'Le client a une adresse avec un numéro de TVA valide mais la boutique affiche des prix avec TVA';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_ead42cb10374a80180e375cd97fb4314'] = 'Vérifiez que le client n\'utilise pas une autre adresse récemment créée et non validée pour le processus d\'achat.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_310686597cbfc21641b62b2020d07288'] = 'Vérifiez que l\'option \"exonération de TVA\" dans la section des paramètres d\'exonération de TVA est activée.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_92d98cd1576470905495f5efbccd96d2'] = 'Vérifiez que le numéro de TVA a bien été validé dans la rubrique \"Gestion du numéro de TVA client\".';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_6bab09cd7d7b98611352ed0c5ec5adcd'] = 'Vérifiez que le client n\'est pas inclus dans la liste de la section de gestion de l\'exonération de TVA du client avec l\'option \"forcer la collecte de la TVA\" sélectionnée.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_6ab787a221c015b92bac35153e152ae9'] = 'Vérifiez si l\'adresse du client correspond au Royaume-Uni et respecte les conditions de perception de la TVA.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_8f0f9049df637c0a87a8817d1ec87f9f'] = 'Vérifiez que l\'adresse que le client a active pour effectuer l\'achat est celle qui correspond à l\'option \"Type d\'adresse\" sélectionnée dans la section de configuration de l\'exonération de TVA.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_c4b52015e73a1758b0f856ffb3675920'] = 'Vérifiez que vous n\'avez pas installé de module qui contrôle les taxes et qui est en conflit avec le module Advanced VAT Manager.';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_058df4f029559cfd28ce27cc82a7fb4e'] = 'Lorsqu\'un client enregistre une adresse avec un numéro de TVA valide et est exonéré de TVA, les prix des produits sont affichés sans TVA mais les prix de la liste des produits sur la page principale continuent d\'être affichés avec TVA';
$_MODULE['<{advancedvatmanager}prestashop>troubleshooting_1d27f6d58f654c4bf9fa41911fe6132f'] = 'Il s\'agit d\'un problème causé par le cache du site. Cela se produit plus fréquemment si vous avez activé le cache Prestashop et l\'option [Never collect template files] dans la section smarty. Pour le résoudre, le cache Prestashop doit être nettoyé. Il est recommandé d\'effectuer un nettoyage périodique du cache Prestashop à l\'aide de tâches CRON.';
$_MODULE['<{advancedvatmanager}prestashop>configure_3f48c57b41a8fd83b522cb0beb195823'] = 'Gestionnaire de TVA avancé - Présentation';
$_MODULE['<{advancedvatmanager}prestashop>configure_d1d2543752be06d0ab0fa3ddd4e71121'] = 'Vérifiez la validité des numéros de TVA des clients qui s\'inscrivent dans le magasin. Gérez les clients avec des numéros de TVA et associez-les automatiquement à des groupes de clients. Supprimez les taxes sur les prix des produits, gérez la politique fiscale du Brexit et bien d\'autres options.';
$_MODULE['<{advancedvatmanager}prestashop>configure_b39bceeded94d6ced6100f53fa488e85'] = 'Ce module a de multiples options et fonctionnalités avancées. Vous devez lire attentivement la documentation du module pour comprendre comment cela fonctionne en général et avec chacune des options. Vous pouvez accéder à la documentation à partir de cette même page de configuration, en entrant dans l\'onglet [Documentation] .';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_b19044bbb08db1e8052ad3372a998f36'] = 'DÉTAILS DE LA TÂCHE CRON';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_a81afedae2e9e6c1ae3fed8374f1a21a'] = 'L\'url à ajouter au serveur de tâches CRON est la suivante :';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_9f82518d468b9fee614fcc92f76bb163'] = 'Magasin';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_f839e61e09022306906a5b72bde401e1'] = 'Cette tâche CRON consiste à vérifier toutes les adresses des clients pour valider le numéro de TVA. Le système analysera uniquement les adresses des clients qui remplissent les conditions configurées dans la page de configuration de ce module. L\'exécution régulière de cette tâche cron protège le fournisseur des achats avec des erreurs d\'application de taxe lorsque le numéro de TVA du client était auparavant valide et n\'est plus valide.';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_5e83dd1817e12d6ceb3c68b1259b859b'] = 'Vous devez configurer une tâche CRON dans votre panneau de serveur (demandez à votre fournisseur de serveur d\'hébergement) ou dans le module Prestashop \"Gestionnaire de tâches Cron\". Vous devez configurer la fréquence d\'exécution de cette tâche CRON. La tâche CRON sera exécutée dépend des options activées ci-dessous.';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_ceed387ac1cd73b1c4e6fa9da29b5c29'] = 'REMARQUE : Il est recommandé d\'exécuter cette tâche CRON pendant les heures creuses pour éviter de détériorer les performances du magasin. Il est également recommandé d\'exécuter cette tâche au moins une fois par jour.';
$_MODULE['<{advancedvatmanager}prestashop>checkvatcron_b00a213e6bffdd3f8309b0ed4bcc5e0a'] = 'La tâche Cron analysera toutes les adresses des clients stockées dans la base de données depuis le début, sauf si vous avez sélectionné l\'option [Continue scan process from last address scanned] .';
$_MODULE['<{advancedvatmanager}prestashop>checkvattool_4dae09dbe896adc9acd2b059395e8383'] = 'Vérifier l\'outil de TVA';
$_MODULE['<{advancedvatmanager}prestashop>checkvattool_eb0fe0bacc4e6726e256c7815a9557a7'] = 'Vous pouvez vérifier les numéros de TVA dans le système VIES ou GOV.UK via cet utilitaire. Si le numéro de TVA est valide, vous obtiendrez toutes les informations liées à l\'enregistrement de ce numéro de TVA (Raison sociale, adresse...).';
$_MODULE['<{advancedvatmanager}prestashop>checkvattool_7cb32e708d6b961d476baced73d362bb'] = 'numéro de TVA';
$_MODULE['<{advancedvatmanager}prestashop>checkvattool_09367387ee4389e5cc42c17e4fc881fd'] = 'Insérer le numéro de TVA...';
