$_MODULE['<{advancedvatmanager}prestashop>information_5c33c6ca398955faf4749e5a44abf6b5'] = 'Dans cette section, vous pouvez ajouter des clients auxquels l\'exonération fiscale sera appliquée ou la taxe sera forcée de s\'appliquer, qu\'ils aient ou non une adresse avec un numéro de TVA valide. Cette liste est compatible avec le mode multi-boutiques et des dérogations peuvent être accordées aux clients dans tous les magasins ou dans n\'importe quel magasin.';
$_MODULE['<{advancedvatmanager}prestashop>information_1f744ebcd0206199d7fcca7159352f94'] = 'Cette option est prioritaire sur les autres options de défiscalisation configurées sur la page de configuration du module.';
$_MODULE['<{advancedvatmanager}prestashop>information_d9be54462f49a36c3fd70aeb8801f116'] = 'Lorsqu\'un client est ajouté à la liste, il bénéficie instantanément soit d\'une exonération de TVA, soit de l\'obligation de payer la TVA, selon l\'option choisie dans \"Option TVA\".';
$_MODULE['<{advancedvatmanager}prestashop>information_04bf2603a145f70ce793e34cd15f1e45'] = 'Cela signifie que, selon l\'option choisie, le client paiera toujours la TVA ou sera exonéré du paiement de la TVA, quelles que soient les autres conditions qu\'il remplit. Si vous souhaitez que le client bénéficie de l\'exonération de TVA selon les conditions standards du module, vous devrez le retirer de cette liste.';
$_MODULE['<{advancedvatmanager}prestashop>form_e0626222614bdee31951d84c64e5e9ff'] = 'Sélectionner';
