$_MODULE['<{advancedvatmanager}prestashop>form_28371256b723459e31636eda1c651af6'] = 'REMARQUE : Le fait qu\'ils soient compatibles ne garantit pas qu\'il est possible que certaines options de notre module ne fonctionnent pas lorsque certains de ces modules sont activés dans le magasin. La compatibilité garantit que les modules installés et fonctionnels peuvent coexister sans générer d\'erreurs ou de conflits entre eux. Uniquement dans les modules totalement intégrés, les fonctionnalités et toutes les options de notre module fonctionnent correctement et sont parfaitement intégrées dans ces modules. Nous vous recommandons d\'acquérir les modules pour lesquels nous avons développé l\'intégration et qui figurent dans la liste d\'intégration';
$_MODULE['<{advancedvatmanager}prestashop>form_e919d64d1fc38215cd5feb014694f1ab'] = 'INSTRUCTIONS DE COMPATIBILITÉ';
$_MODULE['<{advancedvatmanager}prestashop>form_f5596427a7186c3c13aabdc64b7cacc5'] = 'Ce module est conçu pour apporter les modifications nécessaires aux fichiers de remplacement afin d\'assurer la compatibilité entre les modules répertoriés une fois qu\'il est installé, redémarré ou activé. Vous n\'avez aucune action à effectuer de votre part, tout le processus se fait automatiquement. Lorsque notre module est désactivé ou désinstallé, le système de modules renvoie le code d\'origine des remplacements des modules compatibles qui sont activés à ce moment-là.';
$_MODULE['<{advancedvatmanager}prestashop>form_16d06b3f6ba6c0f780a6a587987accf4'] = 'Si vous rencontrez des problèmes avec le code des méthodes de remplacement qui ont été personnalisées auparavant. Le module, chaque fois qu\'il est installé ou activé, enregistre une copie de sauvegarde de tout le contenu du dossier [override] du répertoire racine de la boutique dans le dossier [backup] à l\'intérieur du répertoire du module.';
$_MODULE['<{advancedvatmanager}prestashop>form_74a1f4e0259f786597fbe6f48e45a20b'] = 'Procédure d\'installation ou d\'activation de l\'un des modules indiqués dans cette liste de compatibilité et d\'intégration';
$_MODULE['<{advancedvatmanager}prestashop>form_b94f6bb65017cec7bc1e733b8282f826'] = 'Si vous avez déjà installé notre module et que vous souhaitez installer l\'un des modules indiqués dans cette liste de compatibilité et d\'intégration, il vous suffit de désactiver notre module, d\'installer le module souhaité et enfin d\'activer à nouveau notre module. En activant notre module, le système effectuera la compatibilité sur les dérogations.';
$_MODULE['<{advancedvatmanager}prestashop>form_794df3791a8c800841516007427a2aa3'] = 'Licence';
